// src/pages/Home.jsx
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";
import eveVideo from "../assets/eve_sdm_talk.mp4";

const Home = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [formData, setFormData] = useState({ userName: "", birthday: "" });

  useEffect(() => {
    setHeroData({
      imageUrl: "",
      title: "您好，我是乳房外科小幫手",
      description: "請填寫基本資料，再按下開始。",
    });

    // 組件卸載時，確保語音與影片完全停止防止殘留背景音
    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [setHeroData]);

  // 🔊 核心：連接語音與影片同步的處理函式
  const handleSpeakSpeech = () => {
    if (!window.speechSynthesis) return;

    // 1. 先重設所有狀態
    window.speechSynthesis.cancel();

    // 2. 填入你要小幫手唸的台詞
    const textToSpeak = `您好，我是乳外小幫手伊微。接下來進行治療決策的過程中，在每個決策的步驟，如果有任何疑問隨時提出來喔，都會一直都在，陪您安心走過每一步。`;

    const utterance = new SpeechSynthesisUtterance(textToSpeak);
    utterance.lang = "zh-TW"; // 設定台灣中文
    utterance.rate = 1.0; // 語速

    // 🎬 當語音「真正開始發聲」的那一刻，影片才開始動
    utterance.onstart = () => {
      setIsPlaying(true);
      if (videoRef.current) {
        videoRef.current.muted = true; // 靜音影片，因為聲音由 TTS API 提供
        videoRef.current
          .play()
          .catch((err) => console.log("影片播放受阻：", err));
      }
    };

    // 🛑 當語音「唸完」的那一瞬間，影片立刻停下，嘴巴閉上
    utterance.onend = () => {
      setIsPlaying(false);
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0; // 讓影片回到最初始（閉嘴準備）的幀
      }
    };

    utterance.onerror = () => {
      setIsPlaying(false);
      if (videoRef.current) videoRef.current.pause();
    };

    // 執行發聲
    window.speechSynthesis.speak(utterance);
  };

  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    if (videoRef.current) videoRef.current.pause();

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));
    navigate("/selection");
  };

  return (
    <div className={styles.homeContainer}>
      {/* 大畫面講解區 */}
      <div className={styles.heroVideoContainer} onClick={handleSpeakSpeech}>
        <video
          ref={videoRef}
          src={eveVideo}
          playsInline
          webkit-playsinline="true"
          preload="auto"
          loop // 允許語音很長時影片能循環嘴動
          className={styles.heroVideo}
        />

        {!isPlaying && (
          <div className={styles.videoOverlay}>
            <div className={styles.playIconButton}>🔊</div>
            <p className={styles.playHintText}>點擊讓助理引言講解台詞</p>
          </div>
        )}
      </div>

      <div className={styles.inputWrapper}>
        <Input
          label="請輸入您的姓名"
          name="userName"
          value={formData.userName}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, userName: e.target.value }))
          }
        />
        <Input
          label="請輸入您的出生年月日"
          type="date"
          name="birthday"
          value={formData.birthday}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, birthday: e.target.value }))
          }
        />
      </div>

      <div className={styles.buttonWrapper}>
        <Button onClick={handleStart} fullWidth>
          開始
        </Button>
      </div>
    </div>
  );
};

export default Home;
